#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.GameContent.Buffs;
using MVZ2.Vanilla.Grids;
using MVZ2Logic;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Blueprints;
using MVZ2Logic.Definitions;
using MVZ2Logic.Entities;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Level;
using PVZEngine.SeedPacks;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Artifacts
{
    [AutoArtifactDefinition(VanillaArtifactNames.lilyPlatform)]
    public class LilyPlatform : ArtifactDefinition
    {
        public LilyPlatform(string nsp, string name) : base(nsp, name)
        {
            AddAura(new BlueprintAura());
        }
        public override void PostUpdate(Artifact artifact)
        {
            base.PostUpdate(artifact);
            var auraEffect = artifact.GetAuraEffect<BlueprintAura>();
            if (auraEffect != null && auraEffect.GetTargetCount() > 0)
            {
                artifact.SetGlowing(true);
            }
            else
            {
                artifact.SetGlowing(false);
            }
        }
        public class BlueprintAura : AuraEffectDefinition
        {
            public BlueprintAura() : base(VanillaBuffID.SeedPack.lilyPlatform, 4)
            {
            }
            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var level = auraEffect.Source.GetLevel();
                using var seedPacksItem = level.GetAllSeedPacksDisposeable();
                foreach (var seed in seedPacksItem.Value)
                {
                    if (seed == null)
                        continue;
                    var entityID = seed.GetSeedEntityID();
                    var entityDef = level.Content.GetEntityDefinition(entityID);
                    if (entityDef == null)
                        continue;
                    var layers = entityDef.GetGridLayersToTake();
                    if (layers != null && layers.Contains(VanillaGridLayers.carrier))
                    {
                        results.Add(seed);
                    }
                }
            }
        }
    }
}
